dir:














































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@id_bg, ',')
	select @@fields into #t from v41 a @@join
	  where a.id in (select id from #id)
	  order by a.line, a.id

	select * from #t

	DECLARE @ds_cong VARCHAR(4000)  
	SELECT distinct ma_cong into #tt FROM v41 a where a.id in (select id from #id)
	SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt

	select a.ma_noi_di,a.ma_noi_den,a.ma_kh,a.ma_hang,a.ma_nt,@ds_cong ds_cong,b.ten_noi_di,c.ten_noi_den,d.ten_kh,e.ten_kh ten_hang,a.ngay_hl, a.ngay_hld, id id_bg from s41 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang = e.ma_kh
	where a.id in (select top 1 id from #id order by id desc) 

	drop table #id, #t, #tt









  &DefaultButton;




function filter$t11BQ1Select(p){
  this.constructor(p);
}
filter$t11BQ1Select.prototype = new DirEvent();
filter$t11BQ1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$t11BQ1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._id_bg,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$t11BQ1SetMaster(p);

}

function dir$t11BQ1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$t11BQ1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = "";

	dt.removeRow('[so_luong] == 0');
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong');
    pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
	p._close();

  return false;
}








					DECLARE @ds_cong VARCHAR(4000)  
					SELECT distinct ma_cong into #tt FROM v41 a where a.id = @id
					SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt

					select top 1 a.id_yc as [!id_yc], a.ma_kh as [!ma_kh],d.ten_kh as [!ten_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den],@ds_cong as [!ds_cong], e.ten_kh as [!ten_hang]
					from s41 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang =e.ma_kh
					where a.id = @id
